<?php require_once "../config/database.php";require_once "../includes/functions.php";require_admin();$rows=$pdo->query("SELECT name,brand,stock,status FROM products ORDER BY stock")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include "../includes/navbar.php";?><main class="container page"><span class="eyebrow">ADMIN</span><h1>Inventory.</h1><div class="table-wrap"><table><tr><th>Product</th><th>Brand</th><th>Stock</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r["name"])?></td><td><?=e($r["brand"])?></td><td><?=$r["stock"]?></td><td><?=e($r["status"])?></td></tr><?php endforeach;?></table></div></main></body></html>